// Generated by the pinned Rust SDK, including intermediate Poseidon vectors.
// The stub supplies only the primitive, so wire parsing and all payment policy
// run in Dart without loading a native library in a Flutter unit test.
final fixture = jsonDecode(
  File('test/fixtures/spend_checks.json').readAsStringSync(),
) as Map;
final cases = (fixture['cases'] as List).cast<Map>();
String hex(List<int> bytes) =>
    bytes.map((byte) => byte.toRadixString(16).padLeft(2, '0')).join();
Uint8List bytes(Object? value) =>
    Uint8List.fromList((value as List).cast<int>());

Future<Uint8List> hash(List<Uint8List> inputs) async {
  final result = (fixture['hashes'] as Map)[inputs.map(hex).join(':')];
  if (result == null) throw StateError('Not a Rust Poseidon vector');
  return bytes(result);
}

class Accounts implements SpendCheckAccounts {
  bool wrongNullifier = false;
  bool wrongTokenOwner = false;
  int treeId = 0;

  @override
  Future<Uint8List> registeredNullifier(String owner) async {
    if (wrongNullifier) return Uint8List(32);
    final value = (fixture['nullifiers'] as Map)[owner];
    if (value == null) throw StateError('Not registered');
    return bytes(value);
  }

  @override
  Future<int> outputTreeId(String address) async {
    if (address != fixture['tree']) throw StateError('Not a tree');
    return treeId;
  }

  @override
  Future<bool> tokenAccountMatches(
    String account,
    String owner,
    String mint,
    String program,
  ) async =>
      !wrongTokenOwner &&
      owner == fixture['recipient'] &&
      cases.any(
        (c) =>
            c['mint'] == mint &&
            c['tokenAccount'] == account &&
            c['tokenProgram'] == program,
      );
}

List<OutputOpening> openings(Map example) => [
  for (final o in example['openings'] as List)
    OutputOpening(
      ownerSigningKey: o['ownerSigningKey'] == null
          ? null
          : bytes(o['ownerSigningKey']),
      nullifierKey: o['nullifierKey'] == null ? null : bytes(o['nullifierKey']),
      mint: o['mint'] as String?,
      amount: BigInt.parse(o['amount'] as String),
      blinding: bytes(o['blinding']),
      treeId: o['treeId'] as int,
      compact: o['compact'] as bool,
    ),
];

SpendRequest request(Map example, {int amount = 100, String? recipient}) =>
    SpendRequest(
      mint: example['mint'] as String?,
      outputs: [
        if (example['withdraw'] as bool)
          Output.public(
            recipient: recipient ?? fixture['recipient'] as String,
            amount: BigInt.from(amount),
          )
        else
          Output.private(
            recipient: recipient ?? fixture['recipient'] as String,
            amount: BigInt.from(amount),
          ),
        Output.private(
          recipient: fixture['collector'] as String,
          amount: BigInt.from(5),
        ),
      ],
    );

Future<List<String>> verify(
  Map example, {
  Uint8List? message,
  List<OutputOpening>? outputs,
  SpendRequest? wanted,
  Accounts? accounts,
}) => SpendChecks(accounts ?? Accounts(), hash: hash).verify(
  message: message ?? bytes(example['message']),
  openings: outputs ?? openings(example),
  sender: fixture['sender'] as String,
  request: wanted ?? request(example),
);

OutputOpening changed(
  OutputOpening o, {
  BigInt? amount,
  Uint8List? blinding,
  Uint8List? nullifier,
  int? treeId,
  bool? compact,
  Uint8List? dataHash,
}) => OutputOpening(
  ownerSigningKey: o.ownerSigningKey,
  nullifierKey: nullifier ?? o.nullifierKey,
  mint: o.mint,
  amount: amount ?? o.amount,
  blinding: blinding ?? o.blinding,
  treeId: treeId ?? o.treeId,
  compact: compact ?? o.compact,
  dataHash: dataHash,
);

int find(List<int> haystack, List<int> needle) {
  for (var i = 0; i <= haystack.length - needle.length; i++) {
    if (List.generate(
      needle.length,
      (j) => haystack[i + j] == needle[j],
    ).every((same) => same)) {
      return i;
    }
  }
  throw StateError('Missing fixture bytes');
}

// Offsets of the v1 instruction bodies, used only to target wire mutations.
List<({int header, int accounts, int data, int length})> instructionOffsets(
  Uint8List message,
) {
  final view = ByteData.sublistView(message);
  final mask = view.getUint32(4, Endian.little);
  final count = message[40];
  var offset = 42 + message[41] * 32;
  if (mask & 3 == 3) offset += 8;
  if (mask & 4 != 0) offset += 4;
  if (mask & 8 != 0) offset += 4;
  if (mask & 16 != 0) offset += 4;
  final headers = offset;
  offset += count * 4;
  return [
    for (var i = 0; i < count; i++)
      (() {
        final header = headers + i * 4;
        final accounts = offset;
        final data = accounts + message[header + 1];
        final length = view.getUint16(header + 2, Endian.little);
        offset = data + length;
        return (header: header, accounts: accounts, data: data, length: length);
      })(),
  ];
}

class Pending implements PreparedTransaction {
  Pending(this.example);
  final Map example;
  @override
  Uint8List get message => bytes(example['message']);
  @override
  List<OutputOpening> get outputs => openings(example);
  @override
  List<String> get signers => [fixture['sender'] as String];
  @override
  String get feePayer => signers.single;
  @override
  BigInt get lastValidBlockHeight => BigInt.from(100);
  // Deliberately misleading: checked approvals must come from the UI request.
  @override
  Operation get operation => const Operation.custom(programs: []);
  @override
  bool get isDisposed => false;
  @override
  void dispose() {}
}

class Keys implements native.ProvingKeys {
  @override
  dynamic noSuchMethod(Invocation invocation) => super.noSuchMethod(invocation);
  @override
  void dispose() {}
}

class Backend implements WalletBackend, native.MobileWallet {
  Backend(this.pending);
  final Pending pending;
  Uint8List? signature;
  bool released = false;
  @override
  Future<Uint8List> derivationMessage(String key) async => Uint8List(1);
  @override
  Future<native.MobileWallet> open(
    WalletConfig config,
    String key,
    Uint8List signature,
    NativeTransport transport,
  ) async => this;
  @override
  Future<native.ProvingKeys> provingKeys() async => Keys();
  @override
  Future<String> shieldedAddress() async => 'unused';
  @override
  Future<PreparedTransaction> prepareSpend({
    required List<Output> outputs,
    String? mint,
    String? feePayer,
    Proving? proving,
  }) async => pending;
  @override
  Future<String> submit({
    required PreparedTransaction pending,
    required List<Uint8List> signatures,
  }) async {
    signature = signatures.single;
    return 'submitted';
  }

  @override
  Future<void> release({required PreparedTransaction pending}) async {
    released = true;
  }

  @override
  void dispose() {}
  @override
  dynamic noSuchMethod(Invocation invocation) => super.noSuchMethod(invocation);
}

void main() {
  for (final example in cases) {
    test(
      'accepts Rust ${example['name']} with change, fee and padding',
      () => verify(example),
    );
  }
  final example = cases.first;

  test(
    'the example signer checks before signing and shows checked facts',
    () async {
      final approvals = <String>[];
      final signer = await DemoSigner.fromSeedHex(
        '01' * 32,
        spendChecks: SpendChecks(Accounts(), hash: hash),
        onSign: approvals.add,
      );
      final backend = Backend(Pending(example));
      final wallet = await ZolanaWallet.open(
        signer: signer,
        backend: backend,
        config: const WalletConfig(
          rpcUrl: 'https://rpc.example',
          indexerUrl: 'https://indexer.example',
          provingKeyDir: '/unused',
        ),
      );
      addTearDown(wallet.close);
      final wanted = request(example);
      expect(await signer.spend(wallet, outputs: wanted.outputs), 'submitted');
      expect(
        await Ed25519().verify(
          bytes(example['message']),
          signature: Signature(
            backend.signature!,
            publicKey: SimplePublicKey(
              base58Decode(fixture['sender'] as String),
              type: KeyPairType.ed25519,
            ),
          ),
        ),
        isTrue,
      );
      expect(approvals.last, contains('privately'));
      expect(approvals.last, isNot(contains('Call')));
    },
  );

  test(
    'failed app checks release notes without submitting a signature',
    () async {
      final signer = await DemoSigner.fromSeedHex(
        '01' * 32,
        spendChecks: SpendChecks(Accounts(), hash: hash),
      );
      final backend = Backend(Pending(example));
      final wallet = await ZolanaWallet.open(
        signer: signer,
        backend: backend,
        config: const WalletConfig(
          rpcUrl: 'https://rpc.example',
          indexerUrl: 'https://indexer.example',
          provingKeyDir: '/unused',
        ),
      );
      addTearDown(wallet.close);
      await expectLater(
        signer.spend(wallet, outputs: request(example, amount: 101).outputs),
        throwsStateError,
      );
      expect(backend.signature, isNull);
      expect(backend.released, isTrue);
      // The failed request is cleared: the next approved request may proceed.
      expect(
        await signer.spend(wallet, outputs: request(example).outputs),
        'submitted',
      );
    },
  );

  test(
    'reads registry keys, tree id and token ownership from the app RPC',
    () async {
      final server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
      addTearDown(() => server.close(force: true));
      var wrongOwner = false;
      server.listen((request) async {
        final call = jsonDecode(await utf8.decoder.bind(request).join()) as Map;
        final params = call['params'] as List;
        final Object result;
        if (call['method'] == 'getProgramAccounts') {
          expect(params.first, registryProgram);
          final owner = fixture['recipient'] as String;
          expect((params[1] as Map)['filters'], [
            {'dataSize': 100},
            {
              'memcmp': {'offset': 1, 'bytes': owner},
            },
          ]);
          result = [
            {
              'account': {
                'owner': wrongOwner ? shieldedPoolProgram : registryProgram,
                'data': [
                  base64Encode([
                    1,
                    ...base58Decode(owner),
                    0,
                    ...bytes((fixture['nullifiers'] as Map)[owner]),
                    4,
                    ...List.filled(32, 0),
                    0,
                  ]),
                  'base64',
                ],
              },
            },
          ];
        } else if ((params[1] as Map)['encoding'] == 'base64') {
          expect(params.first, fixture['tree']);
          result = {
            'value': {
              'owner': wrongOwner ? registryProgram : shieldedPoolProgram,
              'data': [
                base64Encode([1, 1, 4, 0]),
                'base64',
              ],
            },
          };
        } else {
          final c = cases.singleWhere((c) => c['name'] == 'spl-withdraw');
          result = {
            'value': {
              'owner': c['tokenProgram'],
              'data': {
                'parsed': {
                  'type': 'account',
                  'info': {
                    'mint': c['mint'],
                    'owner': wrongOwner
                        ? fixture['sender']
                        : fixture['recipient'],
                  },
                },
              },
            },
          };
        }
        request.response.headers.contentType = ContentType.json;
        request.response.write(
          jsonEncode({'jsonrpc': '2.0', 'id': call['id'], 'result': result}),
        );
        await request.response.close();
      });
      final rpc = TestClusterRpc('http://127.0.0.1:${server.port}');
      expect(
        await rpc.registeredNullifier(fixture['recipient'] as String),
        bytes((fixture['nullifiers'] as Map)[fixture['recipient']]),
      );
      expect(await rpc.outputTreeId(fixture['tree'] as String), 4);
      final c = cases.singleWhere((c) => c['name'] == 'spl-withdraw');
      Future<bool> matches() => rpc.tokenAccountMatches(
        c['tokenAccount'] as String,
        fixture['recipient'] as String,
        c['mint'] as String,
        c['tokenProgram'] as String,
      );
      expect(await matches(), isTrue);
      wrongOwner = true;
      await expectLater(
        rpc.registeredNullifier(fixture['recipient'] as String),
        throwsStateError,
      );
      await expectLater(
        rpc.outputTreeId(fixture['tree'] as String),
        throwsStateError,
      );
      expect(await matches(), isFalse);
    },
  );

  test('rejects a changed output discovery tag', () async {
    final message = bytes(example['message']);
    final ix = instructionOffsets(message).single;
    final commitment = ix.data + 1 + 8 + 33 + 16 + 1 + 2 + 1;
    // Sender change uses OwnerTag::Account(0). Point it at another account.
    message[commitment + 33] = 1;
    await expectLater(verify(example, message: message), throwsStateError);
  });

  test('rejects an unapproved fee payer', () async {
    final message = bytes(example['message']);
    message[42] ^= 1; // First byte of the fee payer key in a v1 message.
    await expectLater(verify(example, message: message), throwsStateError);
  });

  test('caps the priority fee carried in the v1 header', () async {
    final original = bytes(example['message']);
    final config = 42 + original[41] * 32;
    final fee = Uint8List(8);
    ByteData.sublistView(fee).setUint64(0, 10001, Endian.little);
    final message = Uint8List.fromList([
      ...original.sublist(0, config),
      ...fee,
      ...original.sublist(config),
    ]);
    final view = ByteData.sublistView(message);
    view.setUint32(4, view.getUint32(4, Endian.little) | 3, Endian.little);
    await expectLater(verify(example, message: message), throwsStateError);
  });

  test('accepts a refreshed blockhash', () async {
    final message = bytes(example['message'])..fillRange(8, 40, 17);
    await verify(example, message: message);
  });

  test('checks the original UI request and the fee', () async {
    await expectLater(
      verify(example, wanted: request(example, amount: 101)),
      throwsStateError,
    );
    await expectLater(
      verify(
        example,
        wanted: request(example, recipient: fixture['sender'] as String),
      ),
      throwsStateError,
    );
    final noFee = SpendRequest(outputs: [request(example).outputs.first]);
    await expectLater(verify(example, wanted: noFee), throwsStateError);
  });

  test(
    'rejects changed openings, hidden owners and unapproved output data',
    () async {
      final original = openings(example);
      for (final replacement in [
        changed(original.first, amount: BigInt.from(8)),
        changed(original.first, blinding: Uint8List(32)),
        changed(original.first, nullifier: Uint8List(32)),
        changed(original.first, treeId: 1),
        changed(original.first, compact: true),
        changed(original.first, dataHash: Uint8List(32)),
      ]) {
        await expectLater(
          verify(example, outputs: [replacement, ...original.skip(1)]),
          throwsStateError,
        );
      }
      await expectLater(
        verify(example, accounts: Accounts()..wrongNullifier = true),
        throwsStateError,
      );
    },
  );

  test('requires every slot in proof order', () async {
    final o = openings(example);
    await expectLater(verify(example, outputs: o.sublist(1)), throwsStateError);
    await expectLater(
      verify(example, outputs: [...o, o.last]),
      throwsStateError,
    );
    await expectLater(
      verify(example, outputs: [o[1], o[0], ...o.skip(2)]),
      throwsStateError,
    );
  });

  test(
    'matches instruction commitments, not arbitrary message bytes',
    () async {
      final message = bytes(example['message']);
      final ix = instructionOffsets(message).single;
      // The first output hash follows tag, expiry, key, salt, legs, data/ring options, output count.
      final commitment = ix.data + 1 + 8 + 33 + 16 + 1 + 2 + 1;
      final original = message.sublist(commitment, commitment + 32);
      message.setRange(commitment, commitment + 32, List.filled(32, 9));
      message.setRange(
        ix.data + ix.length - 100,
        ix.data + ix.length - 68,
        original,
      );
      expect(find(message, original), greaterThan(commitment));
      await expectLater(verify(example, message: message), throwsStateError);
    },
  );

  test('checks public amounts and recipients in the instruction', () async {
    for (final c in cases.where((c) => c['withdraw'] as bool)) {
      await expectLater(
        verify(c, wanted: request(c, amount: 101)),
        throwsStateError,
      );
      final message = bytes(c['message']);
      final ix = instructionOffsets(message).last;
      // Change the last settlement address (SOL recipient / SPL token program).
      message[ix.accounts + message[ix.header + 1] - 1] = 0;
      await expectLater(verify(c, message: message), throwsStateError);
    }
  });

  test('checks existing SPL token account ownership', () async {
    final c = cases.singleWhere((c) => c['name'] == 'spl-withdraw');
    await expectLater(
      verify(c, accounts: Accounts()..wrongTokenOwner = true),
      throwsStateError,
    );
  });

  test(
    'checks ATA creation recipients and rejects other instructions',
    () async {
      final c = cases.singleWhere((c) => c['name'] == 'spl-withdraw-create');
      final message = bytes(c['message']);
      final ix = instructionOffsets(message).first;
      message[ix.accounts + 2] = 0;
      await expectLater(verify(c, message: message), throwsStateError);
      final other = bytes(c['message']);
      other[ix.data] = 2; // RecoverNested instead of CreateIdempotent.
      await expectLater(verify(c, message: other), throwsStateError);
    },
  );

  test(
    'rejects unsupported versions, trailing bytes, truncation and other rails',
    () async {
      final message = bytes(example['message']);
      await expectLater(
        verify(
          example,
          message: Uint8List.fromList([0x80, ...message.skip(1)]),
        ),
        throwsStateError,
      );
      await expectLater(
        verify(example, message: Uint8List.fromList([...message, 0])),
        throwsStateError,
      );
      await expectLater(
        verify(example, message: message.sublist(0, message.length - 1)),
        throwsStateError,
      );
      final ix = instructionOffsets(message).single;
      message[ix.data] = 19;
      await expectLater(verify(example, message: message), throwsStateError);
    },
  );
}
